#!/usr/bin/env bash
# Step B chunk-4 harness skeleton: run the sequential class-incremental TR3D pipeline.
#   Usage: bash tools_incremental/run_incremental.sh <3stage|6stage> [GPUS]
#
# It chains the per-stage configs generated by incremental_learning/gen_incremental_configs.py:
# stage1 -> stage2 -> ... -> stageN, each warm-starting from the previous stage's checkpoint
# (load_from is baked into each config). After each stage it evaluates on that stage's
# CUMULATIVE val set (all classes seen so far).
#
# IMPORTANT: this is the SCAFFOLD. As written it performs *naive sequential fine-tuning*
# (Step C variant 1): each stage just trains on its novel-class GT with no forgetting
# mitigation. The two Step-C insertion points are marked "STEP C HOOK" below:
#   (1) classifier-head expansion / old-weight transfer before training stage t>1
#   (2) offline pseudo-label generation (run prev-stage model over stage-t scenes, merge
#       pseudo boxes for old classes into the training pkl) for the pseudo-labeling variant.
# Neither is implemented here on purpose — Step B is data + scaffolding + design only.
set -euo pipefail

ORDERING="${1:?usage: run_incremental.sh <3stage|6stage> [GPUS]}"
GPUS="${2:-1}"
REPO="$(cd "$(dirname "$0")/.." && pwd)"
CFG_DIR="$REPO/configs/tr3d_incremental/$ORDERING"
[ -d "$CFG_DIR" ] || { echo "no configs at $CFG_DIR (run gen_incremental_configs.py)"; exit 1; }

# stages in numeric order
mapfile -t CFGS < <(ls "$CFG_DIR"/stage*.py | sort -V)
echo "[$ORDERING] ${#CFGS[@]} stages: ${CFGS[*]}"

for CFG in "${CFGS[@]}"; do
  STAGE="$(basename "$CFG" .py)"
  WORK_DIR="$REPO/work_dirs/incremental/$ORDERING/$STAGE"
  echo "=================================================================="
  echo "[$ORDERING/$STAGE] config=$CFG  work_dir=$WORK_DIR  gpus=$GPUS"

  # ----- STEP C HOOK (1): classifier expansion + (2) pseudo-label prepass go here -----
  # if [ "$STAGE" != "stage1" ]; then
  #   python tools_incremental/expand_head.py --prev ... --cfg "$CFG"      # Step C
  #   python tools_incremental/make_pseudo_labels.py --prev ... --cfg "$CFG"  # Step C (pseudo variant)
  # fi
  # ------------------------------------------------------------------------------------

  if [ "$GPUS" -gt 1 ]; then
    bash "$REPO/tools/dist_train.sh" "$CFG" "$GPUS" --work-dir "$WORK_DIR"
  else
    python "$REPO/tools/train.py" "$CFG" --work-dir "$WORK_DIR"
  fi

  echo "[$ORDERING/$STAGE] eval on cumulative val:"
  python "$REPO/tools/test.py" "$CFG" "$WORK_DIR/latest.pth" --eval mAP 2>&1 | tee "$WORK_DIR/eval.log"
done
echo "[$ORDERING] incremental run complete."
